        "rubric": "Tam giác OAB vuông tại B vì AB là tiếp tuyến (0.25đ). Áp dụng định lí Pythagore: OA = √(OB² + AB²) = √(5² + 12²) = 13 cm (0.5đ). sin(AOB) = AB / OA = 12 / 13 (0.25đ)."
