        "rubric": "a) Kẻ OH vuông góc AB, OK vuông góc CD. Vì AB = CD nên OH = OK (hai dây bằng nhau cách đều tâm) (0.5đ). b) Tam giác OHI = tam giác OKI (cạnh huyền - cạnh góc vuông) suy ra IH = IK. Vì H, K là trung điểm của AB, CD nên HA = KC suy ra IA = IC và IB = ID (0.5đ)."
