    "part4": [
      {
        "id": 1,
        "level": "Thông hiểu",
        "question": "Cho đường tròn $(O; R)$ và điểm $A$ nằm ngoài đường tròn. Kẻ tiếp tuyến $AB$ với đường tròn ($B$ là tiếp điểm). Biết $R = 5\\text{ cm}, AB = 12\\text{ cm}$. Tính độ dài đoạn thẳng $OA$ và $\\sin\\widehat{AOB}$.",
        "rubric": "Tam giác OAB vuông tại B vì AB là tiếp tuyến (0.25đ). Áp dụng định lí Pythagore: OA = √(OB² + AB²) = √(5² + 12²) = 13 cm (0.5đ). sin(AOB) = AB / OA = 12 / 13 (0.25đ)."
      },
      {
        "id": 2,
        "level": "Vận dụng",
        "question": "Cho đường tròn $(O)$, hai dây cung $AB$ và $CD$ bằng nhau và cắt nhau tại điểm $I$ bên trong đường tròn. Chứng minh rằng: a) Khoảng cách từ $O$ đến hai dây $AB, CD$ bằng nhau; b) $IA = IC$ và $IB = ID$.",
        "rubric": "a) Kẻ OH vuông góc AB, OK vuông góc CD. Vì AB = CD nên OH = OK (hai dây bằng nhau cách đều tâm) (0.5đ). b) Tam giác OHI = tam giác OKI (cạnh huyền - cạnh góc vuông) suy ra IH = IK. Vì H, K là trung điểm của AB, CD nên HA = KC suy ra IA = IC và IB = ID (0.5đ)."
      },
      {
        "id": 3,
        "level": "Vận dụng cao",
        "question": "Cho nửa đường tròn đường kính $AB = 2R$. Lấy điểm $C$ trên nửa đường tròn. Kẻ $CH \\perp AB$ ($H \\in AB$). Tìm vị trí của điểm $C$ trên nửa đường tròn để diện tích tam giác $CAB$ đạt giá trị lớn nhất.",
        "rubric": "Diện tích tam giác CAB: S = 1/2 * AB * CH = 1/2 * 2R * CH = R * CH (0.5đ). Diện tích S lớn nhất khi đường cao CH lớn nhất. Trong nửa đường tròn, CH ≤ R, dấu '=' xảy ra khi H trùng với tâm O, tức C là điểm chính giữa của cung AB. Khi đó diện tích lớn nhất bằng R² (0.5đ)."
      }
    ]
