        "rubric": "Ta có AB = AC và OB = OC nên AO là trung trực BC => AO vuông góc BC (0.25đ).\nMặt khác tam giác BCD có CD là đường kính nên góc CBD = 90 độ => BD vuông góc BC.\nVì cùng vuông góc với BC nên BD // AO. Đpcm (0.25đ)."
